grep -Fq 'release-manifest.json' "$repo_root/scripts/package.sh" || fail "package.sh misses release manifest sidecar"
grep -Fq 'release-manifest.json' "$repo_root/scripts/package.ps1" || fail "package.ps1 misses release manifest sidecar"
grep -Fq 'generate_release_index.py' "$repo_root/scripts/package.sh" || fail "package.sh misses release index"
grep -Fq 'generate_release_index.py' "$repo_root/scripts/package.ps1" || fail "package.ps1 misses release index"
grep -Fq 'Remove-Item -Force $componentArtifact' "$repo_root/scripts/package.ps1" || fail "package.ps1 does not replace stale component archives"
grep -Fq 'release-index' "$repo_root/cmd/launcher/main.go" || fail "launcher misses network release index"
grep -Fq 'initialize-complete' "$repo_root/cmd/launcher/main.go" || fail "launcher misses initialization completion"
grep -Fq 'NetworkComponentManager' "$repo_root/internal/launcher/network.go" || fail "network component manager is missing"
grep -Fq 'resolve_release_channel.py' "$repo_root/.github/workflows/chuzi-build.yml" || fail "workflow misses centralized channel resolver"
grep -Fq 'chuzi-${{ needs.release_context.outputs.channel }}-${{ matrix.target }}' "$repo_root/.github/workflows/chuzi-build.yml" || fail "workflow misses channel-specific artifact names"
grep -Fq 'pattern: chuzi-${{ needs.release_context.outputs.channel }}-*' "$repo_root/.github/workflows/chuzi-build.yml" || fail "workflow misses channel-specific artifact download"
grep -Fq 'index.json' "$repo_root/.github/workflows/chuzi-build.yml" || fail "workflow misses release index upload"
grep -Fq 'Verify Unix artifact checksums' "$repo_root/.github/workflows/chuzi-build.yml" || fail "workflow misses Unix checksum verification"
grep -Fq 'stable-release:' "$repo_root/.github/workflows/chuzi-build.yml" || fail "workflow misses stable release job"
grep -Fq 'publish-release-catalog:' "$repo_root/.github/workflows/chuzi-build.yml" || fail "workflow misses release catalog publication"
grep -Fq 'inputs.channel' "$repo_root/.github/workflows/chuzi-build.yml" || fail "workflow misses manual release channel selection"
grep -Fq 'workflow_dispatch:' "$repo_root/.github/workflows/release-retry.yml" || fail "release retry workflow misses manual trigger"
grep -Fq 'validate_release_retry_run.sh' "$repo_root/.github/workflows/release-retry.yml" || fail "release retry workflow misses source run validation"
grep -Fq 'gh release create' "$repo_root/.github/workflows/release-retry.yml" || fail "release retry workflow misses GitHub release publication"
