grep -Fq 'artifact_integration:' "$repo_root/.github/workflows/chuzi-build.yml" || fail "workflow misses artifact integration stage"
grep -Fq 'name: ci-worker' "$repo_root/.github/workflows/chuzi-build.yml" || fail "workflow misses worker artifact handoff"
grep -Fq 'name: ci-go-${{ matrix.target }}' "$repo_root/.github/workflows/chuzi-build.yml" || fail "workflow misses Go artifact handoff"
grep -Fq 'test_nightly_package.sh' "$repo_root/.github/workflows/chuzi-build.yml" || fail "workflow misses nightly package contract"
grep -Fq 'test_nightly_artifact_validator.sh' "$repo_root/.github/workflows/chuzi-build.yml" || fail "workflow misses nightly artifact validator contract"
