grep -Fq 'build_windows_slint.ps1' "$repo_root/.github/workflows/chuzi-build.yml" || fail "workflow misses Windows Slint packaging"
grep -Fq 'layout_snapshot' "$repo_root/.github/workflows/chuzi-build.yml" || fail "workflow misses Slint layout snapshot check"
grep -Fq 'i-slint-backend-testing' "$repo_root/ui/windows/Cargo.toml" || fail "Windows Slint manifest misses testing backend"
grep -Fq 'slint-lsp' "$repo_root/ui/windows/README.md" || fail "Windows Slint README misses editor diagnostics"
grep -Fq '800x600' "$repo_root/ui/windows/README.md" || fail "Windows Slint README misses compact viewport"
grep -Fq '1120x760' "$repo_root/ui/windows/README.md" || fail "Windows Slint README misses preferred viewport"
grep -Fq '1440x900' "$repo_root/ui/windows/README.md" || fail "Windows Slint README misses wide viewport"
