grep -Fq 'name: chuzi-windows-installer-exe' "$repo_root/.github/workflows/chuzi-build.yml" || fail "workflow misses Windows installer EXE artifact"
if grep -Fq 'PackagedMsix' "$repo_root/.github/workflows/chuzi-build.yml"; then
  fail "workflow retains MSIX packaging mode"
fi
if grep -Fq 'chuzi-windows-msix' "$repo_root/.github/workflows/chuzi-build.yml"; then
  fail "workflow retains MSIX artifact"
fi
if grep -Eq '^[[:space:]]{2}windows_msix:' "$repo_root/.github/workflows/chuzi-build.yml"; then
  fail "workflow retains duplicate Windows MSIX job"
fi
if grep -Fq 'name: ci-ui-windows' "$repo_root/.github/workflows/chuzi-build.yml"; then
  fail "workflow retains obsolete unpackaged UI artifact"
fi
grep -Fq 'needs: [release_context, go_build, node_checks]' "$repo_root/.github/workflows/chuzi-build.yml" || fail "assemble target dependencies are incomplete"
grep -Fq 'ValidateSet("InstallerExe", "UnpackagedZip")' "$repo_root/scripts/build_windows_slint.ps1" || fail "Windows Slint script misses explicit packaging modes"
grep -Fq 'ISCC.exe' "$repo_root/scripts/build_windows_slint.ps1" || fail "Windows Slint script misses Inno Setup compiler"
grep -Fq 'packaging/windows/Chuzi.iss' "$repo_root/scripts/build_windows_slint.ps1" || fail "Windows Slint script misses installer definition"
grep -Fq 'OutputBaseFilename=ChuziSetup' "$repo_root/packaging/windows/Chuzi.iss" || fail "Windows installer misses stable setup filename"
grep -Fq 'Source: "{#PayloadDir}\*"' "$repo_root/packaging/windows/Chuzi.iss" || fail "Windows installer misses published payload"
grep -Fq 'UninstallDelete' "$repo_root/packaging/windows/Chuzi.iss" || fail "Windows installer misses uninstall cleanup"
grep -Fq 'KeepUserData' "$repo_root/packaging/windows/Chuzi.iss" || fail "Windows uninstall misses user-data retention option"
grep -Fq 'Check: ShouldDeleteUserData' "$repo_root/packaging/windows/Chuzi.iss" || fail "Windows uninstall data cleanup must use a check function"
grep -Fq 'function ShouldDeleteUserData(): Boolean;' "$repo_root/packaging/windows/Chuzi.iss" || fail "Windows uninstall data cleanup check function is missing"
grep -Fq 'prepare_presentmon.ps1' "$repo_root/scripts/assemble_target.ps1" || fail "Windows target assembly misses PresentMon preparation"
grep -Fq 'PresentMon.exe' "$repo_root/scripts/generate_release_manifest.py" || fail "Windows release manifest misses PresentMon component"
grep -Fq 'PresentMon-LICENSE.txt' "$repo_root/scripts/generate_release_manifest.py" || fail "Windows PresentMon component misses its license"
grep -Fq 'CorePayloadDir' "$repo_root/scripts/build_windows_slint.ps1" || fail "Windows Slint script misses Core payload staging"
grep -Fq 'CorePayload' "$repo_root/scripts/build_windows_slint.ps1" || fail "Windows Slint build misses Core payload staging"
grep -Fq 'slint::include_modules!' "$repo_root/ui/windows/src/main.rs" || fail "Windows Slint client does not include generated UI"
grep -Fq 'MainWindow' "$repo_root/ui/windows/ui/main.slint" || fail "Windows Slint shell is missing"
grep -Fq 'First-run checklist' "$repo_root/ui/windows/ui/main.slint" || fail "Windows Slint overview misses first-run checklist"
grep -Fq 'refresh-plugins' "$repo_root/ui/windows/ui/main.slint" || fail "Windows Slint plugin flow is missing"
grep -Fq 'get_account' "$repo_root/ui/windows/src/main.rs" || fail "Windows Slint client misses account lookup"
grep -Fq 'submit_request' "$repo_root/ui/windows/src/main.rs" || fail "Windows Slint client misses task submission"
grep -Fq 'cancel_request' "$repo_root/ui/windows/src/main.rs" || fail "Windows Slint client misses task cancellation"
grep -Fq 'Smoke test installed Slint client' "$repo_root/.github/workflows/chuzi-build.yml" || fail "Windows Slint workflow misses startup smoke test"
grep -Fq 'Assemble Core payload for the Slint package' "$repo_root/.github/workflows/chuzi-build.yml" || fail "Windows Slint workflow misses Core payload assembly"
grep -Fq 'core-call' "$repo_root/ui/windows/src/main.rs" || fail "Windows Slint client misses launcher Core façade"
grep -Fq 'chuzi.core/v1' "$repo_root/internal/coreapi/api.go" || fail "Core API misses API version"
grep -Fq 'EndpointPath' "$repo_root/internal/launcher/core.go" || fail "launcher Core façade misses endpoint derivation"

for obsolete in \
  "$repo_root/ui/windows/Chuzi.Native.Windows.csproj" \
  "$repo_root/ui/windows/CoreApiClient.cs" \
  "$repo_root/ui/windows/CoreServiceController.cs" \
  "$repo_root/ui/windows/LauncherClient.cs" \
  "$repo_root/ui/windows/CorePipeSmoke.csproj" \
  "$repo_root/ui/windows/CoreLifecycleSmoke.csproj" \
  "$repo_root/scripts/build_windows_ui.ps1"; do
  test ! -e "$obsolete" || fail "obsolete WinUI file remains: $obsolete"
done
if rg -n -i 'winui|microsoft\.ui\.xaml|windowsapp|setup-dotnet|build_windows_ui|CoreLifecycleSmoke|CorePipeSmoke' \
  "$repo_root/README.md" "$repo_root/docs" "$repo_root/ui" "$repo_root/.github/workflows" "$repo_root/packaging"; then
  fail "obsolete WinUI references remain outside historical CR records"
fi

echo "build contract validation passed"
